/**
 * OpenCode x402 Auth Plugin
 *
 * Enables OpenCode to authenticate with the x402 Inference Router using
 * wallet-signed ERC-2612 permits for crypto-native payment.
 *
 * @example
 * ```json
 * // opencode.json
 * {
 *   "plugin": ["@lucid-agents/opencode-x402-plugin"],
 *   "provider": {
 *     "x402": {
 *       "npm": "@ai-sdk/openai-compatible",
 *       "options": { "baseURL": "http://localhost:8080/v1" }
 *     }
 *   }
 * }
 * ```
 */
import { createPublicClient, createWalletClient, http, } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { base, baseSepolia, mainnet } from "viem/chains";
import { PermitCache, shouldInvalidatePermit } from "./cache";
import { normalizeTokenName } from "./utils";
// ============================================================================
// Constants
// ============================================================================
const PRIVATE_KEY_REGEX = /^0x[0-9a-fA-F]{64}$/;
/** USDC contract addresses by network */
const USDC_ADDRESSES = {
    "eip155:8453": "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913", // Base Mainnet
    "eip155:84532": "0x036CbD53842c5426634e7929541eC2318f3dCF7e", // Base Sepolia
    "eip155:1": "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48", // Ethereum Mainnet
};
/** Chain configs by CAIP-2 identifier */
const CHAINS = {
    "eip155:8453": base,
    "eip155:84532": baseSepolia,
    "eip155:1": mainnet,
};
/** Default permit cap in token units ($10.00 USDC = 10,000,000 with 6 decimals) */
const DEFAULT_PERMIT_CAP = "10000000";
/** Default permit validity (1 hour) */
const DEFAULT_VALIDITY_SECONDS = 3600;
function normalizePrivateKey(value) {
    if (!value)
        return null;
    const trimmed = value.trim();
    const normalized = trimmed.startsWith("0X") ? `0x${trimmed.slice(2)}` : trimmed;
    return PRIVATE_KEY_REGEX.test(normalized) ? normalized : null;
}
// ============================================================================
// EIP-712 Signing
// ============================================================================
/**
 * EIP-712 domain for ERC-2612 Permit
 */
function getPermitDomain(tokenName, tokenVersion, chainId, verifyingContract) {
    return {
        name: tokenName,
        version: tokenVersion,
        chainId,
        verifyingContract,
    };
}
/**
 * EIP-712 types for ERC-2612 Permit
 */
const PERMIT_TYPES = {
    Permit: [
        { name: "owner", type: "address" },
        { name: "spender", type: "address" },
        { name: "value", type: "uint256" },
        { name: "nonce", type: "uint256" },
        { name: "deadline", type: "uint256" },
    ],
};
/**
 * Generate a random nonce for the permit
 */
function generateNonce() {
    const randomBytes = new Uint8Array(32);
    crypto.getRandomValues(randomBytes);
    // Use first 8 bytes as a numeric nonce (sufficient uniqueness)
    const view = new DataView(randomBytes.buffer);
    return view.getBigUint64(0, false).toString();
}
const ERC2612_NONCES_ABI = [
    {
        type: "function",
        name: "nonces",
        stateMutability: "view",
        inputs: [{ name: "owner", type: "address" }],
        outputs: [{ name: "nonce", type: "uint256" }],
    },
];
async function fetchPermitNonce(chain, token, owner) {
    const publicClient = createPublicClient({
        chain,
        transport: http(),
    });
    return await publicClient.readContract({
        address: token,
        abi: ERC2612_NONCES_ABI,
        functionName: "nonces",
        args: [owner],
    });
}
/**
 * Sign an ERC-2612 permit using the wallet
 */
async function signPermit(wallet, account, config, permitCap) {
    const chain = CHAINS[config.network] || base;
    const chainId = parseInt(config.network.split(":")[1]);
    const deadline = Math.floor(Date.now() / 1000) + DEFAULT_VALIDITY_SECONDS;
    const nonceValue = await fetchPermitNonce(chain, config.asset, account.address);
    const nonce = nonceValue.toString();
    const domain = getPermitDomain(config.tokenName, config.tokenVersion, chainId, config.asset);
    const message = {
        owner: account.address,
        spender: config.facilitatorSigner,
        value: BigInt(permitCap),
        nonce: BigInt(nonce),
        deadline: BigInt(deadline),
    };
    const signature = await wallet.signTypedData({
        account,
        domain,
        types: PERMIT_TYPES,
        primaryType: "Permit",
        message,
    });
    return {
        signature,
        nonce,
        deadline: deadline.toString(),
    };
}
/**
 * Create a complete x402 payment payload
 */
async function createPaymentPayload(wallet, account, config, permitCap) {
    const { signature, nonce, deadline } = await signPermit(wallet, account, config, permitCap);
    const payload = {
        x402Version: 2,
        accepted: {
            scheme: "upto",
            network: config.network,
            asset: config.asset,
            payTo: config.payTo,
            extra: {
                name: config.tokenName,
                version: config.tokenVersion,
            },
        },
        payload: {
            authorization: {
                from: account.address,
                to: config.facilitatorSigner,
                value: permitCap,
                validBefore: deadline,
                nonce,
            },
            signature,
        },
    };
    // Base64 encode for the header
    return btoa(JSON.stringify(payload));
}
// ============================================================================
// Permit Cache Helpers
// ============================================================================
async function createCachedPermit(wallet, account, config, permitCap) {
    const { signature, nonce, deadline } = await signPermit(wallet, account, config, permitCap);
    const payload = {
        x402Version: 2,
        accepted: {
            scheme: "upto",
            network: config.network,
            asset: config.asset,
            payTo: config.payTo,
            extra: {
                name: config.tokenName,
                version: config.tokenVersion,
            },
        },
        payload: {
            authorization: {
                from: account.address,
                to: config.facilitatorSigner,
                value: permitCap,
                validBefore: deadline,
                nonce,
            },
            signature,
        },
    };
    return {
        paymentSig: btoa(JSON.stringify(payload)),
        deadline: parseInt(deadline, 10),
        maxValue: permitCap,
        nonce,
        network: config.network,
        asset: config.asset,
        payTo: config.payTo,
    };
}
function parseErrorResponse(data) {
    if (!data || typeof data !== "object") {
        return null;
    }
    const record = data;
    if (typeof record.code === "string" || typeof record.error === "string") {
        return {
            code: typeof record.code === "string" ? record.code : undefined,
            error: typeof record.error === "string"
                ? record.error
                : typeof record.message === "string"
                    ? record.message
                    : undefined,
            message: typeof record.message === "string" ? record.message : undefined,
        };
    }
    const nested = record.error;
    if (nested && typeof nested === "object") {
        const nestedRecord = nested;
        return {
            code: typeof nestedRecord.code === "string"
                ? nestedRecord.code
                : typeof nestedRecord.type === "string"
                    ? nestedRecord.type
                    : undefined,
            error: typeof nestedRecord.message === "string"
                ? nestedRecord.message
                : typeof nestedRecord.error === "string"
                    ? nestedRecord.error
                    : undefined,
            message: typeof nestedRecord.message === "string" ? nestedRecord.message : undefined,
        };
    }
    return null;
}
async function extractErrorResponse(response) {
    try {
        const data = await response.clone().json();
        return parseErrorResponse(data);
    }
    catch {
        return null;
    }
}
function decodePaymentRequiredHeader(value) {
    try {
        const json = typeof Buffer !== "undefined"
            ? Buffer.from(value, "base64").toString("utf8")
            : atob(value);
        return JSON.parse(json);
    }
    catch {
        return null;
    }
}
function getRequirementPayTo(requirement) {
    if (!requirement)
        return null;
    return requirement.payTo || requirement.pay_to || null;
}
function getRequirementMaxAmountRequired(requirement) {
    if (!requirement?.extra)
        return undefined;
    return (requirement.extra.maxAmountRequired ||
        requirement.extra.max_amount_required ||
        requirement.extra.maxAmount ||
        requirement.extra.max_amount);
}
function applyPaymentRequirement(config, requirement) {
    if (!requirement)
        return config;
    const payTo = getRequirementPayTo(requirement) || config.payTo;
    const extra = requirement.extra;
    const asset = requirement.asset || config.asset;
    const tokenNameRaw = extra?.name || config.tokenName;
    const tokenName = normalizeTokenName(tokenNameRaw, asset);
    return {
        ...config,
        network: requirement.network || config.network,
        asset,
        payTo,
        facilitatorSigner: payTo || config.facilitatorSigner,
        tokenName,
        tokenVersion: extra?.version || config.tokenVersion,
    };
}
// ============================================================================
// Router Configuration
// ============================================================================
/** Cached router config */
let cachedRouterConfig = null;
let cachedRouterUrl = null;
/**
 * Fetch router configuration from /v1/config endpoint
 */
async function fetchRouterConfig(routerUrl) {
    // Return cached config if URL hasn't changed
    if (cachedRouterConfig && cachedRouterUrl === routerUrl) {
        return cachedRouterConfig;
    }
    const response = await fetch(`${routerUrl}/v1/config`);
    if (!response.ok) {
        throw new Error(`Failed to fetch router config: ${response.status}`);
    }
    const data = (await response.json());
    // Extract config from nested response structure
    // The API returns networks[] array with payment config per network
    const network = data.networks?.[0];
    const eip712 = data.eip712_config;
    const asset = network?.asset?.address || USDC_ADDRESSES["eip155:8453"];
    const tokenNameRaw = eip712?.domain_name || "USD Coin";
    const tokenName = normalizeTokenName(tokenNameRaw, asset);
    const config = {
        network: network?.network_id || "eip155:8453",
        asset,
        payTo: network?.pay_to || "",
        facilitatorSigner: network?.pay_to || "", // Same as payTo for now
        tokenName,
        tokenVersion: eip712?.domain_version || "2",
        paymentHeader: data.payment_header || "PAYMENT-SIGNATURE",
    };
    cachedRouterConfig = config;
    cachedRouterUrl = routerUrl;
    return config;
}
/**
 * Get default router config for a network (fallback)
 */
function getDefaultConfig(network) {
    return {
        network,
        asset: USDC_ADDRESSES[network] || USDC_ADDRESSES["eip155:8453"],
        payTo: "", // Must be fetched from router
        facilitatorSigner: "", // Must be fetched from router
        tokenName: "USD Coin",
        tokenVersion: "2",
        paymentHeader: "PAYMENT-SIGNATURE",
    };
}
// ============================================================================
// Plugin Implementation
// ============================================================================
/**
 * OpenCode x402 Auth Plugin
 *
 * Provides wallet-based authentication for x402 payment protocol.
 * Signs ERC-2612 permits to authorize spending on each request.
 */
export async function X402AuthPlugin({ client }) {
    const logMessage = async (level, message, extra) => {
        try {
            if (client.app?.log) {
                await client.app.log({ service: "x402-auth", level, message, extra });
            }
            else {
                const text = extra ? `${message} ${JSON.stringify(extra)}` : message;
                // eslint-disable-next-line no-console
                console[level === "error" ? "error" : "log"](text);
            }
        }
        catch {
            // eslint-disable-next-line no-console
            console.error(`[x402-auth] ${message}`);
        }
    };
    return {
        auth: {
            provider: "x402",
            /**
             * Loader function - called to configure authentication for requests
             */
            loader: async (getAuth, provider) => {
                const auth = await getAuth();
                const normalizedPrivateKey = normalizePrivateKey(auth?.privateKey ?? auth?.key);
                void logMessage("info", "Auth loader invoked", {
                    hasAuth: !!auth,
                    authType: auth?.type,
                    hasPrivateKey: !!normalizedPrivateKey,
                    providerBaseUrl: provider.options?.baseURL,
                });
                // No auth configured yet
                if (!auth || !normalizedPrivateKey) {
                    return {};
                }
                if (auth.type !== "wallet" || auth.privateKey !== normalizedPrivateKey) {
                    await client.auth.set({
                        path: { id: "x402" },
                        body: {
                            type: "wallet",
                            privateKey: normalizedPrivateKey,
                            routerUrl: auth.routerUrl,
                            permitCap: auth.permitCap,
                            network: auth.network,
                        },
                    });
                }
                // Get router URL from provider options or auth config
                const routerUrl = provider.options?.baseURL?.replace(/\/v1\/?$/, "") ||
                    auth.routerUrl ||
                    "http://localhost:8080";
                let routerOrigin = null;
                try {
                    routerOrigin = new URL(routerUrl).origin;
                }
                catch {
                    routerOrigin = null;
                }
                // Initialize wallet
                const account = privateKeyToAccount(normalizedPrivateKey);
                const network = auth.network || "eip155:8453";
                const chain = CHAINS[network] || base;
                const wallet = createWalletClient({
                    account,
                    chain,
                    transport: http(),
                });
                // Get permit cap from config
                const permitCap = auth.permitCap || DEFAULT_PERMIT_CAP;
                // Fetch router config
                let routerConfig;
                try {
                    routerConfig = await fetchRouterConfig(routerUrl);
                }
                catch (error) {
                    void logMessage("warn", "Failed to fetch router config", {
                        routerUrl,
                        error: error instanceof Error ? error.message : String(error),
                    });
                    routerConfig = getDefaultConfig(network);
                }
                const permitCache = new PermitCache();
                const getOrCreatePermit = async (capOverride) => {
                    const cached = permitCache.get(routerConfig.network, routerConfig.asset, routerConfig.payTo);
                    if (cached && (!capOverride || cached.maxValue === capOverride)) {
                        return cached;
                    }
                    if (cached && capOverride && cached.maxValue !== capOverride) {
                        permitCache.invalidate(routerConfig.network, routerConfig.asset, routerConfig.payTo);
                    }
                    const capToUse = capOverride || permitCap;
                    const fresh = await createCachedPermit(wallet, account, routerConfig, capToUse);
                    permitCache.set(fresh);
                    return fresh;
                };
                // Return custom fetch that injects payment signature
                return {
                    fetch: async (input, init) => {
                        let url;
                        if (typeof input === "string") {
                            url = input;
                        }
                        else if (input instanceof URL) {
                            url = input.toString();
                        }
                        else if (typeof Request !== "undefined" && input instanceof Request) {
                            url = input.url;
                        }
                        else if (input && typeof input.url === "string") {
                            url = input.url;
                        }
                        else {
                            url = String(input);
                        }
                        let parsedUrl = null;
                        try {
                            parsedUrl = new URL(url);
                        }
                        catch {
                            if (routerOrigin) {
                                try {
                                    parsedUrl = new URL(url, routerOrigin);
                                }
                                catch {
                                    parsedUrl = null;
                                }
                            }
                        }
                        const pathname = parsedUrl?.pathname || "";
                        const isConfigPath = pathname.endsWith("/v1/config") || pathname.endsWith("/config");
                        const isModelsPath = pathname.endsWith("/v1/models") || pathname.endsWith("/models");
                        const isRouterRequest = routerOrigin && parsedUrl ? parsedUrl.origin === routerOrigin : url.includes("/v1/");
                        // Only inject payment header for API requests to the router
                        if (!isRouterRequest || isConfigPath || isModelsPath) {
                            void logMessage("info", "Skipping payment header injection", {
                                url,
                                routerOrigin: routerOrigin ?? undefined,
                                pathname,
                                isRouterRequest,
                                isConfigPath,
                                isModelsPath,
                            });
                            return fetch(input, init);
                        }
                        try {
                            const sendWithPermit = async (permit) => {
                                const headers = new Headers(init?.headers);
                                const paymentHeader = routerConfig.paymentHeader || "PAYMENT-SIGNATURE";
                                void logMessage("info", "Injecting payment header", {
                                    url,
                                    paymentHeader,
                                });
                                headers.set(paymentHeader, permit.paymentSig);
                                return fetch(input, { ...init, headers });
                            };
                            const permit = await getOrCreatePermit();
                            const response = await sendWithPermit(permit);
                            if (response.status === 402 || response.status === 401) {
                                const error = await extractErrorResponse(response);
                                const paymentRequired = response.headers.get("PAYMENT-REQUIRED");
                                const decoded = paymentRequired
                                    ? decodePaymentRequiredHeader(paymentRequired)
                                    : null;
                                const requirement = decoded?.accepts?.[0];
                                const payTo = getRequirementPayTo(requirement) || "";
                                const extra = requirement?.extra;
                                const maxAmount = getRequirementMaxAmountRequired(requirement);
                                const previousConfig = routerConfig;
                                if (requirement) {
                                    routerConfig = applyPaymentRequirement(routerConfig, requirement);
                                }
                                void logMessage("error", "Payment required", {
                                    status: response.status,
                                    error: error ?? undefined,
                                    paymentRequired: paymentRequired ? "present" : "missing",
                                    requirement: requirement
                                        ? {
                                            network: requirement.network,
                                            asset: requirement.asset,
                                            payTo,
                                            tokenName: extra?.name,
                                            tokenVersion: extra?.version,
                                            maxAmountRequired: maxAmount,
                                        }
                                        : undefined,
                                });
                                if (error && shouldInvalidatePermit(error)) {
                                    permitCache.invalidate(previousConfig.network, previousConfig.asset, previousConfig.payTo);
                                    if (previousConfig.network !== routerConfig.network ||
                                        previousConfig.asset !== routerConfig.asset ||
                                        previousConfig.payTo !== routerConfig.payTo) {
                                        permitCache.invalidate(routerConfig.network, routerConfig.asset, routerConfig.payTo);
                                    }
                                    const refreshed = await getOrCreatePermit(maxAmount);
                                    return sendWithPermit(refreshed);
                                }
                            }
                            return response;
                        }
                        catch (error) {
                            console.error("[x402-auth] Failed to create payment signature:", error);
                            // Fall back to request without payment (will get 402)
                            return fetch(input, init);
                        }
                    },
                };
            },
            /**
             * Authentication methods available in /connect
             */
            methods: [
                {
                    label: "Connect Wallet (Private Key)",
                    type: "api",
                    prompts: [
                        {
                            type: "text",
                            key: "privateKey",
                            message: "Enter your wallet private key (0x-prefixed hex string).\n" +
                                "This will be stored locally and used to sign payment permits.\n" +
                                "WARNING: Never share your private key. Use a dedicated wallet for AI spending.",
                            validate: (value) => {
                                const normalized = normalizePrivateKey(value);
                                return normalized
                                    ? undefined
                                    : "Invalid private key format (expected 0x + 64 hex chars)";
                            },
                        },
                    ],
                    authorize: async (inputs) => {
                        try {
                            const normalizedKey = normalizePrivateKey(inputs.privateKey);
                            if (!normalizedKey) {
                                console.error("[x402-auth] Invalid private key format");
                                return { type: "failed" };
                            }
                            // Verify we can create an account from it
                            const account = privateKeyToAccount(normalizedKey);
                            console.log(`[x402-auth] Wallet connected: ${account.address}`);
                            const existingAuth = await client.auth.get({ path: { id: "x402" } });
                            // Store auth config
                            await client.auth.set({
                                path: { id: "x402" },
                                body: {
                                    ...(existingAuth ?? {}),
                                    type: "wallet",
                                    privateKey: normalizedKey,
                                    routerUrl: existingAuth?.routerUrl || "http://localhost:8080",
                                    permitCap: existingAuth?.permitCap || DEFAULT_PERMIT_CAP,
                                    network: existingAuth?.network || "eip155:8453",
                                },
                            });
                            return { type: "success", key: normalizedKey };
                        }
                        catch (error) {
                            console.error("[x402-auth] Failed to connect wallet:", error);
                            return { type: "failed" };
                        }
                    },
                },
                {
                    label: "Configure Router URL",
                    type: "api",
                    prompts: [
                        {
                            type: "text",
                            key: "routerUrl",
                            message: "Enter the x402 router URL (e.g., http://localhost:8080 or https://router.example.com)",
                            validate: (value) => {
                                try {
                                    // eslint-disable-next-line no-new
                                    new URL(value);
                                    return undefined;
                                }
                                catch {
                                    return "Invalid URL";
                                }
                            },
                        },
                    ],
                    authorize: async (inputs) => {
                        try {
                            // Validate URL
                            const url = new URL(inputs.routerUrl);
                            // Get existing auth
                            const existingAuth = await client.auth.get({ path: { id: "x402" } });
                            const normalizedKey = normalizePrivateKey(existingAuth?.privateKey ?? existingAuth?.key);
                            const nextAuth = {
                                ...(existingAuth ?? {}),
                                type: "wallet",
                                routerUrl: url.origin,
                            };
                            if (normalizedKey) {
                                nextAuth.privateKey = normalizedKey;
                            }
                            // Update with new router URL
                            await client.auth.set({
                                path: { id: "x402" },
                                body: nextAuth,
                            });
                            // Clear cached config so it refetches
                            cachedRouterConfig = null;
                            cachedRouterUrl = null;
                            return { type: "success", key: normalizedKey ?? undefined };
                        }
                        catch (error) {
                            console.error("[x402-auth] Invalid router URL:", error);
                            return { type: "failed" };
                        }
                    },
                },
                {
                    label: "Set Permit Cap",
                    type: "api",
                    prompts: [
                        {
                            type: "text",
                            key: "permitCap",
                            message: "Enter the maximum USDC spending cap per permit session.\n" +
                                "Examples: 1 = $1.00, 10 = $10.00, 100 = $100.00\n" +
                                "This limits how much can be spent before a new permit is needed.",
                            validate: (value) => {
                                const cap = parseFloat(value);
                                return Number.isFinite(cap) && cap > 0 ? undefined : "Invalid cap amount";
                            },
                        },
                    ],
                    authorize: async (inputs) => {
                        try {
                            const cap = parseFloat(inputs.permitCap);
                            if (isNaN(cap) || cap <= 0) {
                                console.error("[x402-auth] Invalid cap amount");
                                return { type: "failed" };
                            }
                            // Convert to USDC units (6 decimals)
                            const permitCap = Math.floor(cap * 1_000_000).toString();
                            // Get existing auth
                            const existingAuth = await client.auth.get({ path: { id: "x402" } });
                            const normalizedKey = normalizePrivateKey(existingAuth?.privateKey ?? existingAuth?.key);
                            const nextAuth = {
                                ...(existingAuth ?? {}),
                                type: "wallet",
                                permitCap,
                            };
                            if (normalizedKey) {
                                nextAuth.privateKey = normalizedKey;
                            }
                            // Update with new cap
                            await client.auth.set({
                                path: { id: "x402" },
                                body: nextAuth,
                            });
                            console.log(`[x402-auth] Permit cap set to $${cap} (${permitCap} units)`);
                            return { type: "success", key: normalizedKey ?? undefined };
